// Render-scale cap unit test (hle_resscale.c): the row is picked by main's build ID only; the game's own requests are only lowered to the cap, never raised; lifting the
// cap gives the game back its last request; DM_RES_CAP is read once and checked; only the game's own modes 1 and 2 are lowered (a menu's mode 0 keeps full size).
// A fake main image, graphics object and dynamic-resolution controller stand in for the game. Expected values are hand-written, not generated by the implementation.
// macOS: clang with the profile header (make GAME=...). Linux / WSL: the Android compat's mach shim (-include ../../android/compat/darwin.h -I../../android/compat);
// this file brings the shim's vm_read_overwrite then (compat.c has the Android one)
#ifndef __APPLE__
#define _GNU_SOURCE   // (process_vm_readv)
#include <sys/uio.h>
#include <unistd.h>
#endif
#include "../hle_resscale.c"
#ifndef __APPLE__
kern_return_t vm_read_overwrite(task_t t, vm_address_t a, vm_size_t n, vm_address_t to, vm_size_t *got) {
    (void)t; struct iovec l = { (void *)to, n }, r = { (void *)a, n }; ssize_t k = process_vm_readv(getpid(), &l, 1, &r, 1, 0);
    if (k < 0) return 1;
    *got = (vm_size_t)k; return KERN_SUCCESS;
}
#endif
module_t g_mod[MAX_MOD]; int g_nmod;
void dm_guest_write_prepare(void *addr, size_t len) { (void)addr; (void)len; }
static int checks, fails;
#define CHECK(c, s) do { checks++; int ok = !!(c); fails += !ok; printf("%s %s\n", ok ? "✓" : "✗", s); } while (0)
static float *req;
static void game_sets(float v) { *req = v; }
static int is(float v) { return *req == v; }
static int32_t *ctl;   // the game's dynamic-resolution controller: mode at +0, override at +0x2c (4 = none)
static void ctl_mode(int32_t m) { ctl[0] = m; }
static void ctl_ovr(int32_t o) { ctl[0x2c / 4] = o; }

int main(void) {
    // no main loaded yet: not ready, and asked again once it is
    CHECK(!dm_res_scale_ready(), "before main is loaded: not ready");
    CHECK(g_row == -2, "before main is loaded: the row is looked up again later");
    // another build of main: not ready
    g_nmod = 1; strcpy(g_mod[0].name, "main"); strcpy(g_mod[0].build_id, "00000000000000000000000000000000");
    CHECK(!dm_res_scale_ready(), "another main build: not ready");
    g_row = -2;
    // Pokémon Shield 1.3.2's main: ready; the graphics object's pointer is a global at main+0x2636738
    uint8_t *img = calloc(1, 0x2637000), *obj = calloc(1, 0x8600); req = (float *)(obj + 0x85c0);
    g_mod[0].base = img; strcpy(g_mod[0].build_id, "a16802625e7826bf83b6f9708e475b91");
    CHECK(dm_res_scale_ready(), "Shield 1.3.2 main: ready");
    dm_res_scale_tick(); CHECK(!g_live, "graphics object not created yet: nothing done");
    memcpy(img + 0x2636738, &obj, sizeof obj);
    game_sets(1.0f); dm_res_scale_tick(); CHECK(g_live && is(1.0f), "no cap: the game's 1.0 stays");
    dm_res_cap_set(0.7f); dm_res_scale_tick(); CHECK(is(1.0f) && !dm_res_scale_applies(), "cap 0.7, no controller yet (the game's mode unknown): 1.0 left alone");
    // the controller [[main+0x26365b8] + 0xd0], made as the game makes it (Shield main+0xf1a8d0): no override (4), then mode 1, its dynamic resolution
    uint8_t *sys = calloc(1, 0x100); ctl = calloc(1, 0x30); memcpy(sys + 0xd0, &ctl, sizeof ctl); memcpy(img + 0x26365b8, &sys, sizeof sys);
    ctl_ovr(4); ctl_mode(1);
    dm_res_scale_tick(); CHECK(is(0.7f) && dm_res_scale_applies(), "cap 0.7, mode 1 (dynamic): 1.0 lowered to 0.7");
    dm_res_scale_tick(); CHECK(is(0.7f), "cap 0.7: stays 0.7 on the next frame");
    game_sets(0.8f); dm_res_scale_tick(); CHECK(is(0.7f), "the game asks 0.8 (a heavy scene): 0.7");
    game_sets(0.001f); dm_res_scale_tick(); CHECK(is(0.001f), "the game asks 0.001 (background): kept, below the cap");
    game_sets(1.0f); dm_res_scale_tick(); CHECK(is(0.7f), "the game asks 1.0 again: 0.7");
    game_sets(0.8f); dm_res_scale_tick();
    dm_res_cap_set(1.0f); dm_res_scale_tick(); CHECK(is(0.8f), "cap lifted: the game's last request (0.8) back");
    game_sets(1.0f); dm_res_scale_tick(); CHECK(is(1.0f), "no cap: the game's 1.0 stays");
    dm_res_cap_set(0.4f); CHECK(dm_res_cap_get() == 1.0f, "cap 0.4 (under 0.5): ignored");
    dm_res_cap_set(1.5f); CHECK(dm_res_cap_get() == 1.0f, "cap 1.5 (over 1): ignored");
    game_sets(5.0f); dm_res_cap_set(0.6f); dm_res_scale_tick(); CHECK(is(5.0f), "an unexpected game value (5.0): left alone");
    game_sets(1.0f); dm_res_scale_tick(); CHECK(is(0.6f), "then a valid one: capped again (0.6)");
    // Sword 1.3.2's main: the same addresses
    g_row = -2; strcpy(g_mod[0].build_id, "a3b75bcd3311385aeed67fbeeb79cbb7");
    CHECK(dm_res_scale_ready() && g_row == 1, "Sword 1.3.2 main: ready (its own row)");
    game_sets(1.0f); dm_res_cap_set(0.85f); dm_res_scale_tick(); CHECK(is(0.85f), "Sword: cap 0.85 applied");
    // the guard's factor: on what the game asks (also where it asks 0.8 itself), still under the cap
    dm_res_cap_set(1.0f); dm_res_factor_set(0.85f);
    game_sets(0.8f); dm_res_scale_tick(); CHECK(is(0.8f * 0.85f), "factor 0.85, the game asks 0.8: 0.68");
    dm_res_scale_tick(); CHECK(is(0.8f * 0.85f), "factor 0.85: stays 0.68 on the next frame (not applied twice)");
    game_sets(0.001f); dm_res_scale_tick(); CHECK(is(0.001f), "factor 0.85, the game asks 0.001 (background): kept as it is");
    game_sets(1.0f); dm_res_cap_set(0.6f); dm_res_scale_tick(); CHECK(is(0.6f), "factor 0.85 under cap 0.6, the game asks 1.0: 0.6");
    dm_res_cap_set(1.0f); dm_res_scale_tick(); CHECK(is(0.85f), "cap lifted, factor 0.85: 0.85");
    dm_res_factor_set(0.4f); dm_res_scale_tick(); CHECK(is(0.85f), "factor 0.4 (under 0.5): ignored");
    dm_res_factor_set(1.0f); dm_res_scale_tick(); CHECK(is(1.0f), "factor back to 1: the game's 1.0");
    // the game's mode: lowered in 1 (dynamic) and 2 (fixed 0.8) only; 0 is a scene pinned to full size (the menus showing Pokémon models, #97), 3 the background
    dm_res_factor_set(0.7f); game_sets(1.0f); dm_res_scale_tick(); CHECK(is(0.7f) && dm_res_scale_applies(), "mode 1, factor 0.7: 0.7");
    ctl_mode(0); game_sets(1.0f); dm_res_scale_tick(); CHECK(is(1.0f) && !dm_res_scale_applies(), "a menu sets mode 0 and writes 1.0: 1.0 stays");
    dm_res_scale_tick(); CHECK(is(1.0f), "mode 0: still 1.0 on the next frame");
    dm_res_cap_set(0.6f); dm_res_scale_tick(); CHECK(is(1.0f), "mode 0 under cap 0.6 (Graphics on Lowest): 1.0 stays");
    ctl_mode(1); game_sets(1.0f); dm_res_scale_tick(); CHECK(is(0.6f) && dm_res_scale_applies(), "the menu closes (mode 1, the game writes 1.0): cap 0.6");
    dm_res_cap_set(1.0f); dm_res_scale_tick(); CHECK(is(0.7f), "cap lifted: factor 0.7 again");
    ctl_mode(0); dm_res_scale_tick(); CHECK(is(1.0f), "mode 0 without the game writing (our 0.7 left over): the game's 1.0 back");
    ctl_mode(2); game_sets(0.8f); dm_res_scale_tick(); CHECK(is(0.8f * 0.7f) && dm_res_scale_applies(), "mode 2 (fixed 0.8), factor 0.7: 0.56");
    ctl_ovr(3); game_sets(0.001f); dm_res_scale_tick(); CHECK(is(0.001f) && !dm_res_scale_applies(), "override 3 (background): its 0.001 kept");
    ctl_ovr(4); ctl_mode(1); game_sets(1.0f); dm_res_scale_tick(); CHECK(is(0.7f), "back in the foreground, mode 1: 0.7");
    ctl_ovr(0); dm_res_scale_tick(); CHECK(is(1.0f) && !dm_res_scale_applies(), "an override of 0 (3 or less wins over the mode): the game's 1.0 back");
    ctl_ovr(4); dm_res_scale_tick(); CHECK(is(0.7f), "override off (4), mode 1: 0.7");
    memset(sys + 0xd0, 0, sizeof ctl); dm_res_scale_tick(); CHECK(is(1.0f) && !dm_res_scale_applies(), "controller gone (mode unknown): the game's 1.0 back");
    memcpy(sys + 0xd0, &ctl, sizeof ctl); dm_res_factor_set(1.0f); dm_res_scale_tick(); CHECK(is(1.0f) && dm_res_scale_applies(), "controller back, factor 1: 1.0");
    // DM_RES_CAP: read once, 0.5 - 1 only
    g_cap_bits = 0; setenv("DM_RES_CAP", "0.75", 1); CHECK(dm_res_cap_get() == 0.75f, "DM_RES_CAP=0.75");
    g_cap_bits = 0; setenv("DM_RES_CAP", "2", 1); CHECK(dm_res_cap_get() == 1.0f, "DM_RES_CAP=2: no cap");
    g_cap_bits = 0; unsetenv("DM_RES_CAP"); CHECK(dm_res_cap_get() == 1.0f, "no DM_RES_CAP: no cap");
    printf("%d checks, %d failed\n", checks, fails);
    return fails != 0;
}
